--liquibase formatted sql
--changeset dev:037-geographie-referentiel

-- Référentiel géographique du Burkina Faso (Pays → Région → Province → Commune), d'après la liste du
-- Ministère de l'Administration territoriale et de la Mobilité (DCRP) : « communes de plein exercice »
-- (149) et « communes de moyen exercice » (200), plus les deux communes à statut particulier,
-- Ouagadougou et Bobo-Dioulasso, absentes de ces listes : 17 régions, 47 provinces, 351 communes.
-- Les identifiants sont déterministes : ils sont les mêmes dans tous les environnements.

CREATE TABLE geo_region (
    id UUID PRIMARY KEY,
    code VARCHAR(40) NOT NULL UNIQUE,
    libelle VARCHAR(80) NOT NULL UNIQUE,
    zone_publication VARCHAR(20) NOT NULL CHECK (zone_publication IN ('KADIOGO', 'GUIRIKO', 'AUTRES_REGIONS'))
);

CREATE TABLE geo_province (
    id UUID PRIMARY KEY,
    region_id UUID NOT NULL REFERENCES geo_region (id),
    code VARCHAR(60) NOT NULL UNIQUE,
    libelle VARCHAR(80) NOT NULL,
    UNIQUE (region_id, libelle)
);

CREATE TABLE geo_commune (
    id UUID PRIMARY KEY,
    province_id UUID NOT NULL REFERENCES geo_province (id),
    code VARCHAR(120) NOT NULL UNIQUE,
    libelle VARCHAR(80) NOT NULL,
    categorie VARCHAR(20) NOT NULL CHECK (categorie IN ('PLEIN', 'MOYEN', 'STATUT_PARTICULIER')),
    UNIQUE (province_id, libelle)
);

CREATE INDEX idx_geo_province_region ON geo_province (region_id);
CREATE INDEX idx_geo_commune_province ON geo_commune (province_id);




-- Origine géographique du déclarant sur le dossier. La zone publiée (colonne region_origine, migration 035)
-- en est déduite par le serveur : Kadiogo, Guiriko, autres régions, ou diaspora pour un pays étranger.
ALTER TABLE dossier
    ADD COLUMN origine_pays VARCHAR(80),
    ADD COLUMN origine_region_id UUID REFERENCES geo_region (id),
    ADD COLUMN origine_province_id UUID REFERENCES geo_province (id),
    ADD COLUMN origine_commune_id UUID REFERENCES geo_commune (id);
